/// <summary>
/// MPJ_25591_CountingReasonCodeEntity
/// Maps the entity to the backing datasources.
/// </summary>
/// <param name = "_entityCtx">The context of the entity.</param>
/// <param name = "_dataSourceCtx">The context of the datasource being mapped.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx,  _dataSourceCtx);
    
    DimensionAttributeValueCombination  dimensionAttributeValueCombination;
    
    if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert
        || _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(InventInventoryCountingReasonCodeEntity,InventCountingReasonCode))
        {
            select firstonly dimensionAttributeValueCombination
                where dimensionAttributeValueCombination.DisplayValue == this.METDisplayValue
                    && dimensionAttributeValueCombination.LedgerDimensionType == LedgerDimensionType::Account;
       
            InventCountingReasonCode dsInventCountingReasonCode = _dataSourceCtx.getBuffer();
            dsInventCountingReasonCode.LedgerDimension =  dimensionAttributeValueCombination.RecId;
        }
    }
}

    /// <summary>
    /// Validating the main account id
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean validateWrite()
    {
        boolean                             ret;
        MainAccount                         mainAccount;
        DimensionAttributeValueCombination  dimensionAttributeValueCombination;

        ret = next validateWrite();

        select firstonly RecId from dimensionAttributeValueCombination
                    where dimensionAttributeValueCombination.DisplayValue == this.METDisplayValue;

        mainAccount = mainAccount::findByLedgerDimension(dimensionAttributeValueCombination.RecId);

        if (!mainAccount)
        {
            ret = checkFailed(strFmt("@MET:MainAccountId", this.METDisplayValue));
        }
        return ret;
    }
